-- ===== 20261115100000_schema.sql =====
-- HolidayVote – schema (concept/03_data_model.md). Same architecture as Esstisch: the phones keep a
-- full SQLite copy and sync with sync_pull (…_changefeed.sql). IDs are created on the device (uuid v7).
--
-- No pictures of holiday homes are stored anywhere: a property keeps only its link; the app fetches
-- the preview picture live from that page.

create table public.profiles (
  id uuid primary key references auth.users (id) on delete cascade,
  display_name text check (char_length(display_name) <= 60),
  terms_accepted_at timestamptz,
  terms_version text,
  banned_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- A vacation = the shared space a group decides in (a "table" in Esstisch).
create table public.vacations (
  id uuid primary key,
  name text not null check (char_length(name) between 1 and 120),
  description text check (char_length(description) <= 2000),
  destination text check (char_length(destination) <= 200),
  start_date date,
  end_date date,
  owner_id uuid not null references public.profiles (id),
  settings text, -- JSON (field config), written by the app as a string
  created_by uuid,
  updated_by uuid,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz
);

create table public.vacation_members (
  id uuid primary key default gen_random_uuid(),
  vacation_id uuid not null references public.vacations (id) on delete cascade,
  user_id uuid not null references public.profiles (id) on delete cascade,
  role text not null default 'member' check (role in ('owner', 'member')),
  display_name text, -- copy of profiles.display_name (other members can't read profiles)
  joined_at timestamptz not null default now(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (vacation_id, user_id)
);

create table public.vacation_invites (
  id uuid primary key default gen_random_uuid(),
  vacation_id uuid not null references public.vacations (id) on delete cascade,
  code text not null unique,
  created_by uuid references public.profiles (id) on delete set null,
  expires_at timestamptz not null default now() + interval '14 days',
  max_uses int not null default 30,
  uses int not null default 0,
  revoked_at timestamptz,
  created_at timestamptz not null default now()
);

-- A holiday home: link + what the group typed in. Deliberately no image column.
create table public.properties (
  id uuid primary key,
  vacation_id uuid not null references public.vacations (id) on delete cascade,
  url text not null check (url ~* '^https?://' and char_length(url) <= 2000),
  title text check (char_length(title) <= 200),
  description text check (char_length(description) <= 2000),
  provider text check (char_length(provider) <= 100),
  price numeric(12, 2) check (price >= 0),
  beds int check (beds between 0 and 999),
  bedrooms int check (bedrooms between 0 and 999),
  bathrooms int check (bathrooms between 0 and 999),
  has_pool smallint not null default 0 check (has_pool in (0, 1)),
  address text check (char_length(address) <= 300),
  lat double precision check (lat between -90 and 90),
  lng double precision check (lng between -180 and 180),
  avatar text check (char_length(avatar) <= 40),
  status text not null default 'active' check (status in ('active', 'eliminated', 'booked')),
  created_by uuid,
  updated_by uuid,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz
);

-- Stars 1–5 per person and house.
create table public.votes (
  id uuid primary key,
  vacation_id uuid not null references public.vacations (id) on delete cascade,
  property_id uuid not null references public.properties (id) on delete cascade,
  user_id uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  value smallint not null check (value between 1 and 5),
  created_by uuid,
  updated_by uuid,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  unique (property_id, user_id)
);

-- One veto per person and vacation (the row stays, property_id moves).
create table public.vetoes (
  id uuid primary key,
  vacation_id uuid not null references public.vacations (id) on delete cascade,
  user_id uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  property_id uuid not null references public.properties (id) on delete cascade,
  created_by uuid,
  updated_by uuid,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  unique (vacation_id, user_id)
);

-- One favourite per person and vacation.
create table public.favorites (
  id uuid primary key,
  vacation_id uuid not null references public.vacations (id) on delete cascade,
  user_id uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  property_id uuid not null references public.properties (id) on delete cascade,
  created_by uuid,
  updated_by uuid,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  unique (vacation_id, user_id)
);

-- Comments; author = created_by (kept when the author leaves, shown without name).
create table public.comments (
  id uuid primary key,
  vacation_id uuid not null references public.vacations (id) on delete cascade,
  property_id uuid not null references public.properties (id) on delete cascade,
  text text not null check (char_length(text) between 1 and 1000),
  stars smallint check (stars between 1 and 5),
  created_by uuid,
  updated_by uuid,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz
);

-- Settings editable without an app release.
create table public.app_config (
  key text primary key,
  value jsonb not null
);
insert into public.app_config (key, value) values
  ('max_properties_per_vacation', '300'),
  ('max_comments_per_vacation', '3000'),
  ('max_vacations_per_owner', '50');

create index vacations_owner_idx on public.vacations (owner_id);
create index vacation_members_user_idx on public.vacation_members (user_id);
create index properties_vacation_idx on public.properties (vacation_id);
create index votes_vacation_idx on public.votes (vacation_id);
create index vetoes_property_idx on public.vetoes (property_id);
create index favorites_property_idx on public.favorites (property_id);
create index comments_property_idx on public.comments (property_id);
create index comments_vacation_idx on public.comments (vacation_id);

-- ===== 20261115100100_functions.sql =====
-- Helpers, triggers and RPCs. SECURITY DEFINER functions set search_path explicitly.
-- Trusted RPCs set app.trusted = on for their transaction; protected columns can only change then.

create or replace function public.config_value(k text)
returns jsonb language sql stable security definer set search_path = public as $$
  select value from public.app_config where key = k;
$$;

-- Banned accounts lose access to everything.
create or replace function public.is_banned()
returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.profiles where id = auth.uid() and banned_at is not null);
$$;

-- Is the current user a member of vacation v?
create or replace function public.is_member(v uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select not public.is_banned() and exists (
    select 1 from public.vacation_members where vacation_id = v and user_id = auth.uid()
  );
$$;

create or replace function public.is_owner(v uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.vacation_members where vacation_id = v and user_id = auth.uid() and role = 'owner'
  );
$$;

create or replace function public.trusted()
returns boolean language sql stable as $$
  select coalesce(current_setting('app.trusted', true), '') = 'on';
$$;

-- updated_at is always set by the server.
create or replace function public.touch_updated_at()
returns trigger language plpgsql as $$
begin
  new.updated_at := now();
  return new;
end $$;

do $$
declare t text;
begin
  foreach t in array array['profiles', 'vacations', 'vacation_members', 'properties', 'votes', 'vetoes', 'favorites', 'comments'] loop
    execute format('create trigger %I before update on public.%I for each row execute function public.touch_updated_at()', t || '_touch', t);
  end loop;
end $$;

-- created_by never changes after the insert ("suggested by …" stays right when others edit).
create or replace function public.keep_created_by()
returns trigger language plpgsql as $$
begin
  if not public.trusted() then
    new.created_by := old.created_by;
  end if;
  return new;
end $$;
do $$
declare t text;
begin
  foreach t in array array['vacations', 'properties', 'votes', 'vetoes', 'favorites', 'comments'] loop
    execute format('create trigger %I before update on public.%I for each row execute function public.keep_created_by()', t || '_keep_created_by', t);
  end loop;
end $$;

-- Profile: terms / ban fields only via our RPCs or the operator.
create or replace function public.protect_profile_columns()
returns trigger language plpgsql as $$
begin
  if not public.trusted() and auth.uid() is not null then
    if tg_op = 'INSERT' then
      new.terms_accepted_at := null;
      new.terms_version := null;
      new.banned_at := null;
    else
      new.terms_accepted_at := old.terms_accepted_at;
      new.terms_version := old.terms_version;
      new.banned_at := old.banned_at;
    end if;
  end if;
  return new;
end $$;
create trigger profiles_protect before insert or update on public.profiles
  for each row execute function public.protect_profile_columns();

-- Vacation: the owner only changes through our RPCs (leave / recovery).
create or replace function public.protect_vacation_columns()
returns trigger language plpgsql as $$
begin
  if not public.trusted() and tg_op = 'UPDATE' then
    new.owner_id := old.owner_id;
  end if;
  return new;
end $$;
create trigger vacations_protect before insert or update on public.vacations
  for each row execute function public.protect_vacation_columns();

-- Creating a vacation makes the creator its owner (clients can't insert memberships directly).
create or replace function public.add_owner_membership()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if (select count(*) from public.vacations where owner_id = new.owner_id)
     > coalesce(public.config_value('max_vacations_per_owner')::text::int, 50) then
    raise exception 'limit_vacations' using errcode = '23514';
  end if;
  insert into public.vacation_members (vacation_id, user_id, role, display_name)
  select new.id, new.owner_id, 'owner', p.display_name
  from public.profiles p where p.id = new.owner_id
  on conflict (vacation_id, user_id) do nothing;
  return new;
end $$;
create trigger vacations_owner_membership after insert on public.vacations
  for each row execute function public.add_owner_membership();

-- Keep the member display name copy in sync.
create or replace function public.copy_display_name()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  update public.vacation_members set display_name = new.display_name
  where user_id = new.id and display_name is distinct from new.display_name;
  return new;
end $$;
create trigger profiles_display_name after insert or update of display_name on public.profiles
  for each row execute function public.copy_display_name();

-- Votes, vetoes, favourites and comments must point to a house of the same vacation.
create or replace function public.check_same_vacation()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if not exists (select 1 from public.properties where id = new.property_id and vacation_id = new.vacation_id) then
    raise exception 'property % is not part of vacation %', new.property_id, new.vacation_id using errcode = '23514';
  end if;
  return new;
end $$;
do $$
declare t text;
begin
  foreach t in array array['votes', 'vetoes', 'favorites', 'comments'] loop
    execute format('create trigger %I before insert or update on public.%I for each row execute function public.check_same_vacation()', t || '_same_vacation', t);
  end loop;
end $$;

-- Houses: only the owner books / eliminates; only the owner or the person who suggested it deletes it.
-- Silently kept instead of an error: the rest of the change (e.g. a new price) still goes through.
create or replace function public.protect_property_columns()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if public.trusted() or auth.uid() is null then
    return new;
  end if;
  if tg_op = 'INSERT' then
    if not public.is_owner(new.vacation_id) then new.status := 'active'; end if;
    if (select count(*) from public.properties where vacation_id = new.vacation_id)
       >= coalesce(public.config_value('max_properties_per_vacation')::text::int, 300) then
      raise exception 'limit_properties' using errcode = '23514';
    end if;
    return new;
  end if;
  new.vacation_id := old.vacation_id;
  if new.status is distinct from old.status and not public.is_owner(old.vacation_id) then
    new.status := old.status;
  end if;
  if new.deleted_at is distinct from old.deleted_at
     and not (public.is_owner(old.vacation_id) or old.created_by = auth.uid()) then
    new.deleted_at := old.deleted_at;
  end if;
  return new;
end $$;
create trigger properties_protect before insert or update on public.properties
  for each row execute function public.protect_property_columns();

create or replace function public.limit_comments()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if (select count(*) from public.comments where vacation_id = new.vacation_id)
     >= coalesce(public.config_value('max_comments_per_vacation')::text::int, 3000) then
    raise exception 'limit_comments' using errcode = '23514';
  end if;
  return new;
end $$;
create trigger comments_limit before insert on public.comments
  for each row execute function public.limit_comments();

-- Someone leaves / is removed: their stars, veto and favourite at that vacation go too (comments stay).
-- Account recovery moves the membership to the new account (user_id old → new): they move along.
create or replace function public.picks_follow_member()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'DELETE' then
    delete from public.votes where vacation_id = old.vacation_id and user_id = old.user_id;
    delete from public.vetoes where vacation_id = old.vacation_id and user_id = old.user_id;
    delete from public.favorites where vacation_id = old.vacation_id and user_id = old.user_id;
    return old;
  end if;
  if new.user_id is distinct from old.user_id then
    update public.votes set user_id = new.user_id where vacation_id = new.vacation_id and user_id = old.user_id;
    update public.vetoes set user_id = new.user_id where vacation_id = new.vacation_id and user_id = old.user_id;
    update public.favorites set user_id = new.user_id where vacation_id = new.vacation_id and user_id = old.user_id;
  end if;
  return new;
end $$;
create trigger vacation_members_picks after delete or update of user_id on public.vacation_members
  for each row execute function public.picks_follow_member();

-- ---------- terms of use (UGC rules) ----------

create or replace function public.accept_terms(p_version text)
returns void language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then
    raise exception 'not_signed_in' using errcode = '42501';
  end if;
  perform set_config('app.trusted', 'on', true);
  insert into public.profiles (id, terms_accepted_at, terms_version)
  values (auth.uid(), now(), p_version)
  on conflict (id) do update set terms_accepted_at = now(), terms_version = p_version;
end $$;

create or replace function public.require_terms()
returns void language plpgsql stable security definer set search_path = public as $$
begin
  if public.is_banned() then
    raise exception 'banned' using errcode = '42501';
  end if;
  if not exists (select 1 from public.profiles where id = auth.uid() and terms_accepted_at is not null) then
    raise exception 'terms_required' using errcode = 'P0001';
  end if;
end $$;

-- ---------- invites ----------

-- Short codes without ambiguous characters (no 0/O, 1/I/L).
create or replace function public.random_invite_code()
returns text language sql volatile as $$
  select string_agg(substr('ABCDEFGHJKMNPQRSTUVWXYZ23456789', 1 + floor(random() * 31)::int, 1), '')
  from generate_series(1, 6);
$$;

create or replace function public.create_invite(p_vacation uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_code text;
  v_expires timestamptz;
begin
  if auth.uid() is null or not public.is_member(p_vacation) then
    raise exception 'not_a_member' using errcode = '42501';
  end if;
  perform public.require_terms();
  loop
    v_code := public.random_invite_code();
    begin
      insert into public.vacation_invites (vacation_id, code, created_by)
      values (p_vacation, v_code, auth.uid())
      returning expires_at into v_expires;
      exit;
    exception when unique_violation then
      -- try another code
    end;
  end loop;
  return jsonb_build_object('code', v_code, 'expires_at', v_expires);
end $$;

-- Joining is refused without accepted terms or if a block exists in either direction.
create or replace function public.check_join_allowed(p_vacation uuid)
returns void language plpgsql stable security definer set search_path = public as $$
begin
  perform public.require_terms();
  if exists (
    select 1 from public.vacation_members m
    join public.user_blocks b
      on (b.blocker_id = auth.uid() and b.blocked_id = m.user_id)
      or (b.blocked_id = auth.uid() and b.blocker_id = m.user_id)
    where m.vacation_id = p_vacation
  ) then
    raise exception 'blocked' using errcode = 'P0001';
  end if;
end $$;

create or replace function public.accept_invite(p_code text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_inv public.vacation_invites;
  v_vac public.vacations;
  v_name text;
begin
  if auth.uid() is null then
    raise exception 'not_signed_in' using errcode = '42501';
  end if;

  select * into v_inv from public.vacation_invites
  where code = upper(trim(p_code)) and revoked_at is null and expires_at > now() and uses < max_uses
  for update;
  if not found then
    raise exception 'invalid_code' using errcode = 'P0001';
  end if;

  select * into v_vac from public.vacations where id = v_inv.vacation_id and deleted_at is null;
  if not found then
    raise exception 'invalid_code' using errcode = 'P0001';
  end if;

  if exists (select 1 from public.vacation_members where vacation_id = v_vac.id and user_id = auth.uid()) then
    return jsonb_build_object('vacation_id', v_vac.id, 'vacation_name', v_vac.name, 'status', 'already_member');
  end if;

  perform public.check_join_allowed(v_vac.id);

  insert into public.profiles (id) values (auth.uid()) on conflict (id) do nothing;
  select display_name into v_name from public.profiles where id = auth.uid();
  insert into public.vacation_members (vacation_id, user_id, role, display_name)
  values (v_vac.id, auth.uid(), 'member', v_name);
  update public.vacation_invites set uses = uses + 1 where id = v_inv.id;

  return jsonb_build_object('vacation_id', v_vac.id, 'vacation_name', v_vac.name, 'status', 'joined');
end $$;

-- ---------- leaving, removing, deleting ----------

-- Leave a vacation. The owner hands over to the longest-standing member; the last one deletes it.
create or replace function public.leave_vacation(p_vacation uuid)
returns void language plpgsql security definer set search_path = public as $$
declare
  v_next uuid;
begin
  if auth.uid() is null then
    raise exception 'not_signed_in' using errcode = '42501';
  end if;
  perform set_config('app.trusted', 'on', true);
  if public.is_owner(p_vacation) then
    select user_id into v_next from public.vacation_members
    where vacation_id = p_vacation and user_id <> auth.uid()
    order by joined_at
    limit 1;
    if v_next is null then
      delete from public.vacations where id = p_vacation; -- cascades to all its data
      return;
    end if;
    update public.vacation_members set role = 'owner' where vacation_id = p_vacation and user_id = v_next;
    update public.vacations set owner_id = v_next where id = p_vacation;
  end if;
  delete from public.vacation_members where vacation_id = p_vacation and user_id = auth.uid();
end $$;

create or replace function public.remove_member(p_vacation uuid, p_user uuid)
returns void language plpgsql security definer set search_path = public as $$
begin
  if not public.is_owner(p_vacation) or p_user = auth.uid() then
    raise exception 'not_allowed' using errcode = '42501';
  end if;
  delete from public.vacation_members where vacation_id = p_vacation and user_id = p_user;
end $$;

-- Owner deletes the vacation for everyone (everything in it goes, the phones remove it on the next sync).
create or replace function public.delete_vacation(p_vacation uuid)
returns void language plpgsql security definer set search_path = public as $$
begin
  if not public.is_owner(p_vacation) then
    raise exception 'not_allowed' using errcode = '42501';
  end if;
  delete from public.vacations where id = p_vacation;
end $$;

-- "Delete my data": leaves every vacation (handing over or deleting it), then deletes profile + account.
create or replace function public.delete_my_account()
returns void language plpgsql security definer set search_path = public as $$
declare
  v uuid;
begin
  if auth.uid() is null then
    raise exception 'not_signed_in' using errcode = '42501';
  end if;
  for v in select vacation_id from public.vacation_members where user_id = auth.uid() loop
    perform public.leave_vacation(v);
  end loop;
  -- Vacations the user created but is no longer a member of (edge case): delete them.
  delete from public.vacations where owner_id = auth.uid();
  delete from public.profiles where id = auth.uid();
  delete from auth.users where id = auth.uid();
end $$;

-- ===== 20261115100200_rls.sql =====
-- Row-level security: every row is visible / writable only for members of its vacation.

alter table public.profiles enable row level security;
alter table public.vacations enable row level security;
alter table public.vacation_members enable row level security;
alter table public.vacation_invites enable row level security;
alter table public.properties enable row level security;
alter table public.votes enable row level security;
alter table public.vetoes enable row level security;
alter table public.favorites enable row level security;
alter table public.comments enable row level security;
alter table public.app_config enable row level security;

-- profiles: own profile only; names of others come via vacation_members.display_name.
create policy profiles_select on public.profiles for select to authenticated using (id = auth.uid());
create policy profiles_insert on public.profiles for insert to authenticated with check (id = auth.uid());
create policy profiles_update on public.profiles for update to authenticated using (id = auth.uid()) with check (id = auth.uid());

-- vacations: members read; the creator inserts (owner = self); only the owner edits / deletes.
create policy vacations_select on public.vacations for select to authenticated
  using (public.is_member(id) or owner_id = auth.uid());
create policy vacations_insert on public.vacations for insert to authenticated
  with check (owner_id = auth.uid() and not public.is_banned());
create policy vacations_update on public.vacations for update to authenticated
  using (public.is_owner(id)) with check (public.is_owner(id));
create policy vacations_delete on public.vacations for delete to authenticated
  using (public.is_owner(id));

-- vacation_members: read own memberships + members of my vacations; changes only via RPCs.
create policy vacation_members_select on public.vacation_members for select to authenticated
  using (user_id = auth.uid() or public.is_member(vacation_id));

-- vacation_invites: only via RPCs; members may list and revoke.
create policy vacation_invites_select on public.vacation_invites for select to authenticated
  using (public.is_member(vacation_id));
create policy vacation_invites_update on public.vacation_invites for update to authenticated
  using (public.is_member(vacation_id)) with check (public.is_member(vacation_id));

-- properties: members add and edit; status / delete rules in protect_property_columns().
create policy properties_select on public.properties for select to authenticated using (public.is_member(vacation_id));
create policy properties_insert on public.properties for insert to authenticated
  with check (public.is_member(vacation_id) and created_by = auth.uid());
create policy properties_update on public.properties for update to authenticated
  using (public.is_member(vacation_id)) with check (public.is_member(vacation_id));
create policy properties_delete on public.properties for delete to authenticated
  using (public.is_owner(vacation_id) or (public.is_member(vacation_id) and created_by = auth.uid()));

-- votes / vetoes / favorites: everyone at the vacation sees them; each person writes only their own.
do $$
declare t text;
begin
  foreach t in array array['votes', 'vetoes', 'favorites'] loop
    execute format('create policy %I on public.%I for select to authenticated using (public.is_member(vacation_id))', t || '_select', t);
    execute format('create policy %I on public.%I for insert to authenticated with check (user_id = auth.uid() and public.is_member(vacation_id))', t || '_insert', t);
    execute format('create policy %I on public.%I for update to authenticated using (user_id = auth.uid() and public.is_member(vacation_id)) with check (user_id = auth.uid() and public.is_member(vacation_id))', t || '_update', t);
    execute format('create policy %I on public.%I for delete to authenticated using (user_id = auth.uid() and public.is_member(vacation_id))', t || '_delete', t);
  end loop;
end $$;

-- comments: everyone reads; each person writes and deletes only their own.
create policy comments_select on public.comments for select to authenticated using (public.is_member(vacation_id));
create policy comments_insert on public.comments for insert to authenticated
  with check (created_by = auth.uid() and public.is_member(vacation_id));
create policy comments_update on public.comments for update to authenticated
  using (created_by = auth.uid() and public.is_member(vacation_id)) with check (created_by = auth.uid() and public.is_member(vacation_id));
create policy comments_delete on public.comments for delete to authenticated
  using (created_by = auth.uid() and public.is_member(vacation_id));

-- app_config: readable, never writable by clients.
create policy app_config_select on public.app_config for select to authenticated using (true);

grant usage on schema public to authenticated;
grant select, insert, update, delete on public.profiles, public.vacations, public.properties, public.votes,
  public.vetoes, public.favorites, public.comments to authenticated;
grant select, update on public.vacation_invites to authenticated;
grant select on public.vacation_members, public.app_config to authenticated;

revoke all on function public.random_invite_code(), public.check_join_allowed(uuid), public.require_terms()
  from public, anon;
grant execute on function public.create_invite(uuid), public.accept_invite(text), public.leave_vacation(uuid),
  public.remove_member(uuid, uuid), public.delete_vacation(uuid), public.delete_my_account(),
  public.accept_terms(text) to authenticated;

-- ===== 20261115100300_moderation.sql =====
-- User-generated content (App Store guideline 1.2 / Google Play UGC policy), as in Esstisch:
-- terms accepted before sharing (accept_terms / require_terms), reporting, blocking, operator ban.

-- Reports: members report content of their vacation; only the operator reads them.
-- reporter_id is nullable: reports stay for the operator after the reporter deletes their account.
create table public.content_reports (
  id uuid primary key default gen_random_uuid(),
  reporter_id uuid default auth.uid() references public.profiles (id) on delete set null,
  vacation_id uuid not null references public.vacations (id) on delete cascade,
  target_type text not null check (target_type in ('property', 'comment', 'member')),
  target_id uuid not null,
  reason text not null check (reason in ('offensive', 'illegal', 'spam', 'other')),
  note text check (char_length(note) <= 1000),
  status text not null default 'open' check (status in ('open', 'removed', 'dismissed')),
  created_at timestamptz not null default now(),
  handled_at timestamptz
);
create index content_reports_open_idx on public.content_reports (status, created_at);
alter table public.content_reports enable row level security;
create policy content_reports_insert on public.content_reports for insert to authenticated
  with check (reporter_id = auth.uid() and public.is_member(vacation_id));
grant insert on public.content_reports to authenticated;

-- Blocking: blocked people can't share a vacation with the blocker again.
create table public.user_blocks (
  blocker_id uuid not null references public.profiles (id) on delete cascade,
  blocked_id uuid not null references public.profiles (id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (blocker_id, blocked_id)
);
alter table public.user_blocks enable row level security;
create policy user_blocks_own on public.user_blocks for select to authenticated using (blocker_id = auth.uid());
grant select on public.user_blocks to authenticated;

-- Block a member of my vacation: report + block; the owner removes the person, others leave.
create or replace function public.block_member(p_vacation uuid, p_user uuid, p_reason text default 'offensive')
returns void language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null or p_user = auth.uid() or not public.is_member(p_vacation) then
    raise exception 'not_allowed' using errcode = '42501';
  end if;
  insert into public.user_blocks (blocker_id, blocked_id) values (auth.uid(), p_user) on conflict do nothing;
  insert into public.content_reports (reporter_id, vacation_id, target_type, target_id, reason)
  values (auth.uid(), p_vacation, 'member', p_user, coalesce(p_reason, 'offensive'));
  if public.is_owner(p_vacation) then
    delete from public.vacation_members where vacation_id = p_vacation and user_id = p_user;
  else
    perform public.leave_vacation(p_vacation);
  end if;
end $$;
grant execute on function public.block_member(uuid, uuid, text) to authenticated;

-- ---------- operator tools (SQL editor / service role only) ----------

create or replace view public.moderation_queue as
  select r.id, r.created_at, r.reason, r.note, r.target_type, r.target_id, r.vacation_id, v.name as vacation_name,
         r.reporter_id,
         case r.target_type
           when 'property' then (select coalesce(title, url) from public.properties where id = r.target_id)
           when 'comment' then (select text from public.comments where id = r.target_id)
           when 'member' then (select display_name from public.profiles where id = r.target_id)
         end as target_label
  from public.content_reports r left join public.vacations v on v.id = r.vacation_id
  where r.status = 'open'
  order by r.created_at;
revoke all on public.moderation_queue from anon, authenticated;

create or replace function public.moderate_ban_user(p_user uuid)
returns void language plpgsql security definer set search_path = public as $$
begin
  perform set_config('app.trusted', 'on', true);
  update public.profiles set banned_at = now() where id = p_user;
  delete from public.vacation_members where user_id = p_user and role = 'member';
end $$;

-- Open reports with everything needed to decide (moderation page → Edge Function `moderation`).
create or replace function public.moderation_report_details()
returns jsonb language sql stable security definer set search_path = public as $$
  select coalesce(jsonb_agg(r order by (r ->> 'created_at')), '[]'::jsonb) from (
    select jsonb_build_object(
      'id', c.id,
      'created_at', c.created_at,
      'reason', c.reason,
      'note', c.note,
      'target_type', c.target_type,
      'target_id', c.target_id,
      'vacation', jsonb_build_object('id', v.id, 'name', v.name,
                 'members', (select count(*) from public.vacation_members m where m.vacation_id = v.id)),
      'reporter', jsonb_build_object('id', c.reporter_id,
                 'name', coalesce((select display_name from public.vacation_members m where m.vacation_id = c.vacation_id and m.user_id = c.reporter_id),
                                  (select display_name from public.profiles where id = c.reporter_id))),
      'reports_on_target', (select count(*) from public.content_reports x where x.target_id = c.target_id),
      'target', case c.target_type
        when 'property' then (
          select jsonb_build_object('title', p.title, 'url', p.url, 'description', p.description, 'address', p.address,
                   'deleted', p.deleted_at is not null,
                   'author_id', p.created_by, 'author_name', (select display_name from public.profiles where id = p.created_by))
          from public.properties p where p.id = c.target_id)
        when 'comment' then (
          select jsonb_build_object('text', k.text, 'deleted', k.deleted_at is not null,
                   'property', (select coalesce(title, url) from public.properties where id = k.property_id),
                   'author_id', k.created_by, 'author_name', (select display_name from public.profiles where id = k.created_by))
          from public.comments k where k.id = c.target_id)
        when 'member' then (
          select jsonb_build_object('name', coalesce(m.display_name, p.display_name), 'role', m.role,
                   'still_member', m.user_id is not null, 'banned', p.banned_at is not null, 'author_id', p.id)
          from public.profiles p left join public.vacation_members m on m.user_id = p.id and m.vacation_id = c.vacation_id
          where p.id = c.target_id)
      end
    ) as r
    from public.content_reports c join public.vacations v on v.id = c.vacation_id
    where c.status = 'open'
  ) x;
$$;

-- Act on a report: dismiss | remove (soft delete → synced away from all phones; a reported person is
-- removed from that vacation) | ban (remove + ban its author).
create or replace function public.moderate_report(p_report uuid, p_action text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  c public.content_reports;
  v_author uuid;
begin
  select * into c from public.content_reports where id = p_report;
  if c.id is null then
    raise exception 'unknown_report' using errcode = 'P0002';
  end if;
  if p_action not in ('dismiss', 'remove', 'ban') then
    raise exception 'unknown_action' using errcode = '22023';
  end if;

  if p_action in ('remove', 'ban') then
    perform set_config('app.trusted', 'on', true);
    case c.target_type
      when 'property' then
        select created_by into v_author from public.properties where id = c.target_id;
        update public.properties set deleted_at = now() where id = c.target_id and deleted_at is null;
      when 'comment' then
        select created_by into v_author from public.comments where id = c.target_id;
        update public.comments set deleted_at = now() where id = c.target_id and deleted_at is null;
      when 'member' then
        v_author := c.target_id;
        delete from public.vacation_members where vacation_id = c.vacation_id and user_id = c.target_id and role = 'member';
    end case;
    if p_action = 'ban' and v_author is not null then
      perform public.moderate_ban_user(v_author);
    end if;
  end if;

  update public.content_reports
     set status = case when p_action = 'dismiss' then 'dismissed' else 'removed' end, handled_at = now()
   where status = 'open' and (id = p_report or (p_action <> 'dismiss' and target_id = c.target_id));

  return jsonb_build_object('status', case when p_action = 'dismiss' then 'dismissed' else 'removed' end);
end $$;

revoke all on function public.moderate_ban_user(uuid), public.moderation_report_details(), public.moderate_report(uuid, text)
  from public, anon, authenticated;
grant execute on function public.moderation_report_details(), public.moderate_report(uuid, text) to service_role;

-- ===== 20261115100400_changefeed.sql =====
-- Own sync, the same as Esstisch (concept/02_architecture.md § 5).
--
-- The phones keep a full SQLite copy of their vacations. They
--   * upload local changes with normal PostgREST upserts / deletes (row-level security applies), and
--   * download changes with ONE call: sync_pull(cursors).
--
-- Every synced row carries `sync_xid` = id of the transaction that last wrote it. sync_pull returns
-- the rows with sync_xid >= the client's cursor and a new cursor = xmin of the current snapshot, so no
-- change is skipped even if transactions commit out of order (some rows may come twice – ignored).
-- Hard deletes are recorded in sync_deletes. Realtime: one empty Broadcast message per transaction
-- and vacation on the private channel "vacation:<id>"; the app then pulls (and polls every minute).

-- 1. change stamp ------------------------------------------------------------------------------
create or replace function public.stamp_sync_xid()
returns trigger language plpgsql as $$
begin
  new.sync_xid := pg_current_xact_id()::text::bigint;
  return new;
end $$;

do $$
declare t text;
begin
  foreach t in array array['profiles', 'vacations', 'vacation_members', 'properties', 'votes', 'vetoes', 'favorites', 'comments'] loop
    execute format('alter table public.%I add column if not exists sync_xid bigint not null default 0', t);
    execute format('create trigger %I before insert or update on public.%I for each row execute function public.stamp_sync_xid()',
                   t || '_sync_xid', t);
  end loop;
  foreach t in array array['properties', 'votes', 'vetoes', 'favorites', 'comments'] loop
    execute format('create index %I on public.%I (vacation_id, sync_xid)', t || '_sync_idx', t);
  end loop;
end $$;

-- 2. hard deletes ------------------------------------------------------------------------------
create table public.sync_deletes (
  id bigint generated always as identity primary key,
  vacation_id uuid not null,
  tbl text not null,
  row_id uuid not null,
  sync_xid bigint not null default pg_current_xact_id()::text::bigint,
  deleted_at timestamptz not null default now()
);
create index sync_deletes_vacation_idx on public.sync_deletes (vacation_id, sync_xid);
alter table public.sync_deletes enable row level security;
create policy sync_deletes_select on public.sync_deletes for select to authenticated using (public.is_member(vacation_id));
grant select on public.sync_deletes to authenticated;

create or replace function public.log_sync_delete()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  insert into public.sync_deletes (vacation_id, tbl, row_id)
  values (coalesce((to_jsonb(old) ->> 'vacation_id')::uuid, old.id), tg_table_name, old.id);
  return old;
end $$;

do $$
declare t text;
begin
  foreach t in array array['vacations', 'properties', 'votes', 'vetoes', 'favorites', 'comments'] loop
    execute format('create trigger %I after delete on public.%I for each row execute function public.log_sync_delete()',
                   t || '_sync_delete', t);
  end loop;
end $$;

-- Deletion records are kept 60 days (cron). A phone whose cursor is older gets a full copy instead.
insert into public.app_config (key, value) values ('sync_deletes_purged_xid', '0') on conflict (key) do nothing;

create or replace function public.purge_sync_deletes()
returns void language plpgsql security definer set search_path = public as $$
declare v_max bigint;
begin
  select max(sync_xid) into v_max from public.sync_deletes where deleted_at < now() - interval '60 days';
  if v_max is null then return; end if;
  delete from public.sync_deletes where sync_xid <= v_max;
  update public.app_config set value = to_jsonb(v_max + 1) where key = 'sync_deletes_purged_xid';
  delete from public.sync_ticks k where not exists (select 1 from public.vacations v where v.id = k.vacation_id);
end $$;
revoke all on function public.purge_sync_deletes() from public, anon, authenticated;

-- 3. realtime "something changed" signal (Broadcast from Database) -------------------------------
-- No foreign key on purpose: rows deleted by a cascading delete still bump it.
create table public.sync_ticks (
  vacation_id uuid primary key,
  at timestamptz not null default now(),
  xid bigint not null default 0
);
alter table public.sync_ticks enable row level security;

-- One message per transaction and vacation: the first row of a transaction stores its id; every further
-- row of it finds it there and sends nothing (importing 50 rows = 1 message).
create or replace function public.bump_sync_tick()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  r jsonb := to_jsonb(coalesce(new, old));
  v uuid := case when tg_table_name = 'vacations' then (r ->> 'id')::uuid else (r ->> 'vacation_id')::uuid end;
  x bigint := pg_current_xact_id()::text::bigint;
  n int;
begin
  if v is null then
    return null;
  end if;
  insert into public.sync_ticks as k (vacation_id, at, xid) values (v, now(), x)
  on conflict (vacation_id) do update set at = excluded.at, xid = excluded.xid where k.xid <> excluded.xid;
  get diagnostics n = row_count;
  if n > 0 then
    begin
      -- No content: the app only learns "something changed" and pulls with its own rights.
      perform realtime.send('{}'::jsonb, 'changed', 'vacation:' || v::text, true);
    exception when others then
      -- The signal is a nicety – a Realtime hiccup must never undo the user's change.
      raise warning 'realtime.send failed for vacation %: %', v, sqlerrm;
    end;
  end if;
  return null;
end $$;

do $$
declare t text;
begin
  foreach t in array array['vacations', 'vacation_members', 'properties', 'votes', 'vetoes', 'favorites', 'comments'] loop
    execute format('create trigger %I after insert or update or delete on public.%I for each row execute function public.bump_sync_tick()',
                   t || '_sync_tick', t);
  end loop;
end $$;

-- Who may listen: topic "vacation:<uuid>" → member of that vacation (not banned).
create or replace function public.can_listen_to_topic(p_topic text)
returns boolean language sql stable security definer set search_path = public as $$
  select case
    when p_topic ~ '^vacation:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      then public.is_member(substr(p_topic, 10)::uuid)
    else false
  end;
$$;
revoke all on function public.can_listen_to_topic(text) from public, anon;
grant execute on function public.can_listen_to_topic(text) to authenticated;

drop policy if exists holidayvote_vacation_signal_receive on realtime.messages;
create policy holidayvote_vacation_signal_receive on realtime.messages
  for select to authenticated
  using (realtime.messages.extension = 'broadcast' and public.can_listen_to_topic((select realtime.topic())));
-- No insert policy: clients can't send on these channels, only the database does.

-- 4. download ----------------------------------------------------------------------------------
-- p_cursors: {"<vacation id>": <cursor>, …} as returned by the previous call (missing = everything).
-- Runs with the caller's rights: row-level security decides what is returned.
create or replace function public.sync_pull(p_cursors jsonb default '{}'::jsonb)
returns jsonb language plpgsql
set search_path = public
set timezone = 'UTC'
as $$
declare
  v_uid uuid := auth.uid();
  v_horizon bigint := pg_snapshot_xmin(pg_current_snapshot())::text::bigint;
  v_purged bigint := coalesce((select value::text::bigint from public.app_config where key = 'sync_deletes_purged_xid'), 0);
  v_out jsonb := '{}'::jsonb;
  v uuid;
  c bigint;
begin
  if v_uid is null then
    raise exception 'not_signed_in' using errcode = '42501';
  end if;
  for v in
    select m.vacation_id from public.vacation_members m
    where m.user_id = v_uid and public.is_member(m.vacation_id)
  loop
    c := coalesce((p_cursors ->> v::text)::bigint, 0);
    v_out := v_out || jsonb_build_object(v::text, jsonb_build_object(
      -- cursor older than the kept deletion records: the app replaces its copy of this vacation
      'full', c > 0 and c < v_purged,
      'rows', jsonb_build_object(
        'vacations', (select coalesce(jsonb_agg(to_jsonb(x) - 'sync_xid'), '[]') from public.vacations x
                      where x.id = v and (x.sync_xid >= c or c < v_purged)),
        'properties', (select coalesce(jsonb_agg(to_jsonb(x) - 'sync_xid'), '[]') from public.properties x
                      where x.vacation_id = v and (x.sync_xid >= c or c < v_purged)),
        'votes', (select coalesce(jsonb_agg(to_jsonb(x) - 'sync_xid'), '[]') from public.votes x
                      where x.vacation_id = v and (x.sync_xid >= c or c < v_purged)),
        'vetoes', (select coalesce(jsonb_agg(to_jsonb(x) - 'sync_xid'), '[]') from public.vetoes x
                      where x.vacation_id = v and (x.sync_xid >= c or c < v_purged)),
        'favorites', (select coalesce(jsonb_agg(to_jsonb(x) - 'sync_xid'), '[]') from public.favorites x
                      where x.vacation_id = v and (x.sync_xid >= c or c < v_purged)),
        'comments', (select coalesce(jsonb_agg(to_jsonb(x) - 'sync_xid'), '[]') from public.comments x
                      where x.vacation_id = v and (x.sync_xid >= c or c < v_purged))
      ),
      'deletes', case when c = 0 or c < v_purged then '[]'::jsonb else (
        select coalesce(jsonb_agg(jsonb_build_array(d.tbl, d.row_id)), '[]') from public.sync_deletes d
        where d.vacation_id = v and d.sync_xid >= c) end
    ));
  end loop;

  return jsonb_build_object(
    'cursor', v_horizon,
    'profile', (select to_jsonb(p) - 'sync_xid' - 'terms_accepted_at' - 'terms_version' - 'banned_at'
                from public.profiles p where p.id = v_uid),
    -- own memberships + the members of my vacations; small, always complete
    'members', (select coalesce(jsonb_agg(to_jsonb(m) - 'sync_xid'), '[]') from public.vacation_members m),
    'vacations', v_out
  );
end $$;

revoke all on function public.sync_pull(jsonb) from public, anon;
grant execute on function public.sync_pull(jsonb) to authenticated;

-- ===== 20261115100500_recovery.sql =====
-- Recovery code: get your vacations back on a new phone without any login (same as Esstisch).
-- The code is shown once in the app (Settings → "New or lost phone?"); only its SHA-256 hash is stored.
-- recover_account(code), called by the new phone's (anonymous) account, moves memberships, ownership,
-- votes, name and terms over to it and deletes the old account – so a lost phone loses access at once.

create table public.account_recovery (
  user_id uuid primary key references auth.users (id) on delete cascade,
  code_hash text not null unique,
  created_at timestamptz not null default now()
);
alter table public.account_recovery enable row level security; -- no policies: only via the functions below

-- Failed attempts, for rate limiting (per account and overall).
create table public.recovery_attempts (
  id bigint generated always as identity primary key,
  user_id uuid not null,
  attempted_at timestamptz not null default now()
);
create index recovery_attempts_time_idx on public.recovery_attempts (attempted_at);
alter table public.recovery_attempts enable row level security;

create or replace function public.recovery_hash(p_code text)
returns text language sql immutable as $$
  select encode(sha256(convert_to(upper(regexp_replace(coalesce(p_code, ''), '[^A-Za-z0-9]', '', 'g')), 'UTF8')), 'hex');
$$;

-- 12 characters from 31 unambiguous ones (no 0/O, 1/I/L) ≈ 59 bits, from gen_random_uuid()
-- (cryptographically strong). Formatted as XXXX-XXXX-XXXX.
create or replace function public.random_recovery_code()
returns text language plpgsql volatile as $$
declare
  alphabet constant text := 'ABCDEFGHJKMNPQRSTUVWXYZ23456789';
  bytes bytea := uuid_send(gen_random_uuid()) || uuid_send(gen_random_uuid());
  code text := '';
  i int;
begin
  for i in 0..11 loop
    code := code || substr(alphabet, 1 + (get_byte(bytes, i) % 31), 1);
  end loop;
  return substr(code, 1, 4) || '-' || substr(code, 5, 4) || '-' || substr(code, 9, 4);
end $$;

-- New code for the current account (replaces an older one). Returns the code – the only time it's visible.
create or replace function public.create_recovery_code()
returns text language plpgsql security definer set search_path = public as $$
declare v_code text;
begin
  if auth.uid() is null then
    raise exception 'not_signed_in' using errcode = '42501';
  end if;
  loop
    v_code := public.random_recovery_code();
    begin
      insert into public.account_recovery (user_id, code_hash) values (auth.uid(), public.recovery_hash(v_code))
      on conflict (user_id) do update set code_hash = excluded.code_hash, created_at = now();
      exit;
    exception when unique_violation then
      -- same code as someone else's (practically impossible): try another one
    end;
  end loop;
  return v_code;
end $$;

-- When the current account's code was created (null = none).
create or replace function public.recovery_code_created_at()
returns timestamptz language sql stable security definer set search_path = public as $$
  select created_at from public.account_recovery where user_id = auth.uid();
$$;

-- Take over the account that owns `p_code`. Returns {display_name, vacations} or {error: 'invalid_code'}.
create or replace function public.recover_account(p_code text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_new uuid := auth.uid();
  v_old uuid;
  v_old_profile public.profiles;
  v_count int;
begin
  if v_new is null then
    raise exception 'not_signed_in' using errcode = '42501';
  end if;
  if (select count(*) from public.recovery_attempts where user_id = v_new and attempted_at > now() - interval '1 hour') >= 10
     or (select count(*) from public.recovery_attempts where attempted_at > now() - interval '1 hour') >= 1000 then
    raise exception 'too_many_attempts' using errcode = 'P0001';
  end if;

  select user_id into v_old from public.account_recovery where code_hash = public.recovery_hash(p_code);
  if v_old is null then
    -- Returned, not raised: an exception would roll back the recorded attempt (and the rate limit).
    insert into public.recovery_attempts (user_id) values (v_new);
    return jsonb_build_object('error', 'invalid_code');
  end if;
  if v_old = v_new then
    return jsonb_build_object('display_name', (select display_name from public.profiles where id = v_new), 'vacations', 0);
  end if;
  select * into v_old_profile from public.profiles where id = v_old;
  if v_old_profile.banned_at is not null then
    raise exception 'blocked' using errcode = '42501';
  end if;

  perform set_config('app.trusted', 'on', true);
  insert into public.profiles (id) values (v_new) on conflict (id) do nothing;

  -- Memberships (a vacation both accounts are in keeps the new one). Votes, vetoes and favourites follow
  -- the membership (trigger picks_follow_member).
  delete from public.vacation_members m
   where m.user_id = v_old and exists (select 1 from public.vacation_members x where x.vacation_id = m.vacation_id and x.user_id = v_new);
  update public.vacation_members set user_id = v_new where user_id = v_old;
  get diagnostics v_count = row_count;

  update public.vacations set owner_id = v_new where owner_id = v_old;
  -- "suggested by …" / authorship stays correct.
  update public.vacations set created_by = v_new where created_by = v_old;
  update public.vacations set updated_by = v_new where updated_by = v_old;
  update public.properties set created_by = v_new where created_by = v_old;
  update public.properties set updated_by = v_new where updated_by = v_old;
  update public.comments set created_by = v_new where created_by = v_old;
  update public.comments set updated_by = v_new where updated_by = v_old;
  update public.votes set created_by = v_new, updated_by = v_new where user_id = v_new;
  update public.vetoes set created_by = v_new, updated_by = v_new where user_id = v_new;
  update public.favorites set created_by = v_new, updated_by = v_new where user_id = v_new;
  update public.vacation_invites set created_by = v_new where created_by = v_old;
  update public.content_reports set reporter_id = v_new where reporter_id = v_old;
  insert into public.user_blocks (blocker_id, blocked_id, created_at)
    select v_new, blocked_id, created_at from public.user_blocks where blocker_id = v_old and blocked_id <> v_new
    on conflict do nothing;
  insert into public.user_blocks (blocker_id, blocked_id, created_at)
    select blocker_id, v_new, created_at from public.user_blocks where blocked_id = v_old and blocker_id <> v_new
    on conflict do nothing;

  update public.profiles set
    display_name = coalesce(v_old_profile.display_name, display_name),
    terms_accepted_at = coalesce(v_old_profile.terms_accepted_at, terms_accepted_at),
    terms_version = coalesce(v_old_profile.terms_version, terms_version)
  where id = v_new;

  -- The same code keeps working for the new phone.
  delete from public.account_recovery where user_id = v_new;
  update public.account_recovery set user_id = v_new where user_id = v_old;

  -- The old phone loses access: its account is deleted (cascades to what's left of it).
  delete from public.profiles where id = v_old;
  delete from auth.users where id = v_old;

  return jsonb_build_object('display_name', v_old_profile.display_name, 'vacations', v_count);
end $$;

revoke all on function public.create_recovery_code(), public.recovery_code_created_at(), public.recover_account(text)
  from public, anon;
grant execute on function public.create_recovery_code(), public.recovery_code_created_at(), public.recover_account(text)
  to authenticated;
revoke all on function public.random_recovery_code(), public.recovery_hash(text) from public, anon, authenticated;

-- Old failed attempts are only needed for the hourly limit.
create or replace function public.prune_recovery_attempts()
returns void language sql security definer set search_path = public as $$
  delete from public.recovery_attempts where attempted_at < now() - interval '1 day';
$$;
revoke all on function public.prune_recovery_attempts() from public, anon, authenticated;

-- Tombstones (soft-deleted rows) older than 30 days are removed for good (logged in sync_deletes).
create or replace function public.prune_tombstones()
returns void language plpgsql security definer set search_path = public as $$
begin
  delete from public.comments where deleted_at < now() - interval '30 days';
  delete from public.votes where deleted_at < now() - interval '30 days';
  delete from public.properties where deleted_at < now() - interval '30 days';
  delete from public.vacations where deleted_at < now() - interval '30 days';
  delete from public.vacation_invites where expires_at < now() - interval '30 days';
end $$;
revoke all on function public.prune_tombstones() from public, anon, authenticated;

-- ===== 20261115100600_cron.sql =====
-- Scheduled jobs (Supabase only: pg_cron, pg_net, Vault – skipped in the PGlite tests).
create extension if not exists pg_cron;
create extension if not exists pg_net with schema extensions;

select cron.schedule('holidayvote-purge-sync-deletes', '30 3 * * *', $$select public.purge_sync_deletes()$$);
select cron.schedule('holidayvote-prune-recovery-attempts', '40 3 * * *', $$select public.prune_recovery_attempts()$$);
select cron.schedule('holidayvote-prune-tombstones', '50 3 * * *', $$select public.prune_tombstones()$$);

-- Daily e-mail about new content reports: calls the Edge Function report-digest at 07:00 UTC. Needs two
-- Vault secrets (supabase/README.md "Report e-mail"): project_url, report_digest_secret. Without them: nothing.
select cron.schedule('holidayvote-report-digest', '0 7 * * *', $$
  select net.http_post(
    url := (select decrypted_secret from vault.decrypted_secrets where name = 'project_url') || '/functions/v1/report-digest',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'x-digest-secret', (select decrypted_secret from vault.decrypted_secrets where name = 'report_digest_secret')
    ),
    body := '{}'::jsonb,
    timeout_milliseconds := 60000
  )
  where exists (select 1 from vault.decrypted_secrets where name = 'report_digest_secret')
    and exists (select 1 from vault.decrypted_secrets where name = 'project_url');
$$);

-- ===== 20261115110000_preview_info.sql =====
-- What the listing page says (OpenGraph title / description / site name), stored with the link so houses
-- can be searched. TEXT ONLY: pictures (and picture URLs) are never stored on the server – every phone keeps
-- its own preview cache (src/data/media/previewCache.ts). sync_pull returns the new columns automatically.
alter table public.properties
  add column preview_title text check (char_length(preview_title) <= 300),
  add column preview_description text check (char_length(preview_description) <= 2000),
  add column preview_site text check (char_length(preview_site) <= 100);

-- ===== 20261116120000_push_devices.sql =====
-- Push notifications for new houses added to a vacation.
-- All participants (except the person who added the house) get notified.
-- iPhone: the server sends via Apple's push service (Edge Function push-houses).
-- Android: not yet (phones poll or local only).
-- Registered via register_push_device(); iOS needs APNS_KEY_P8/APNS_KEY_ID/APNS_TEAM_ID secrets.

-- Devices that can receive pushes.
create table public.push_devices (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  platform text not null check (platform in ('ios', 'android')),
  apns_token text unique,            -- iOS: device token for Apple's push service
  secret_hash text unique,           -- Android: SHA-256 of the secret the phone asks with
  environment text check (environment in ('production', 'sandbox')),  -- iOS: learned on first send
  tz text not null,
  locale text not null default 'de',
  updated_at timestamptz not null default now(),
  check ((platform = 'ios') = (apns_token is not null) and (platform = 'android') = (secret_hash is not null))
);
alter table public.push_devices enable row level security;

-- Sent messages, so we never send twice.
create table public.push_sent (
  device_id uuid not null references public.push_devices (id) on delete cascade,
  kind text not null,
  local_date date not null,
  sent_at timestamptz not null default now(),
  primary key (device_id, kind, local_date)
);
alter table public.push_sent enable row level security;

-- One row per new house per vacation member who should be notified.
create table public.push_events (
  id uuid primary key default gen_random_uuid(),
  vacation_id uuid not null references public.vacations (id) on delete cascade,
  property_id uuid not null references public.properties (id) on delete cascade,
  house_title text not null,
  added_by uuid not null references public.profiles (id) on delete cascade,
  added_by_name text,
  created_at timestamptz not null default now()
);
alter table public.push_events enable row level security;

-- Register / update this phone. Called by the app at start and when settings change.
-- Returns {server: true} when the server now handles pushes for this phone.
create or replace function public.register_push_device(
  p_platform text, p_token text, p_tz text, p_locale text
) returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_hash text := encode(sha256(convert_to(p_token, 'UTF8')), 'hex');
begin
  if auth.uid() is null then
    raise exception 'not_signed_in' using errcode = '42501';
  end if;
  if p_platform not in ('ios', 'android') or length(coalesce(p_token, '')) < 32 then
    raise exception 'bad_device' using errcode = '22023';
  end if;
  if p_platform = 'ios' then
    insert into public.push_devices (user_id, platform, apns_token, tz, locale)
    values (auth.uid(), 'ios', p_token, p_tz, left(coalesce(p_locale, 'de'), 2))
    on conflict (apns_token) do update set user_id = excluded.user_id, tz = excluded.tz,
      locale = excluded.locale, updated_at = now();
  else
    insert into public.push_devices (user_id, platform, secret_hash, tz, locale)
    values (auth.uid(), 'android', v_hash, p_tz, left(coalesce(p_locale, 'de'), 2))
    on conflict (secret_hash) do update set user_id = excluded.user_id, tz = excluded.tz,
      locale = excluded.locale, updated_at = now();
  end if;
  return jsonb_build_object('ok', true);
end $$;

-- iPhone: house-addition notifications due now. Called by the Edge Function push-houses.
create or replace function public.push_due_house(p_now timestamptz default now())
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v_out jsonb := '[]'::jsonb;
  d public.push_devices;
  e public.push_events;
  v_local timestamp;
  v_msg jsonb;
  v_vac public.vacations;
begin
  for d in select * from public.push_devices where platform = 'ios' loop
    v_local := p_now at time zone d.tz;

    -- Only during the day (08:00–21:00 local).
    if v_local::time < '08:00' or v_local::time >= '21:00' then
      continue;
    end if;

    -- Not sent to this device yet.
    if exists (
      select 1 from public.push_sent s
      where s.device_id = d.id and s.kind = 'house' and s.local_date = v_local::date
    ) then
      continue;
    end if;

    -- New houses in this phone's vacations, added by someone else, not yet sent.
    for e in select pe.id, pe.property_id, pe.house_title, pe.added_by, pe.added_by_name, pe.created_at,
                     p.title, p.url, pe.vacation_id
              from public.push_events pe
              join public.properties p on p.id = pe.property_id
             where pe.vacation_id in (
               select m.vacation_id from public.vacation_members m
               where m.user_id = d.user_id
             )
               and pe.added_by is distinct from d.user_id
               and not exists (
                 select 1 from public.push_sent s
                 where s.device_id = d.id and s.kind = 'house:' || pe.id
               )
              order by pe.created_at
    loop
      select * into v_vac from public.vacations where id = e.vacation_id;
      v_msg := jsonb_build_object(
        'show', true,
        'title', case when d.locale = 'en' then 'New holiday home' else 'Neues Ferienhaus' end,
        'body', case when d.locale = 'en'
          then coalesce(e.added_by_name, 'Someone') || ' added "' || coalesce(e.house_title, e.property_id::text) || '" to "' || v_vac.name || '".'
          else coalesce(e.added_by_name, 'Jemand') || ' hat "' || coalesce(e.house_title, e.property_id::text) || '" zu "' || v_vac.name || '" hinzugefügt.'
        end
      );
      v_out := v_out || jsonb_build_object(
        'device_id', d.id, 'token', d.apns_token, 'environment', d.environment,
        'kind', 'house:' || e.id, 'local_date', v_local::date,
        'title', v_msg ->> 'title', 'body', v_msg ->> 'body',
        'route', '/vacations/' || e.vacation_id || '/houses/' || e.property_id
      );
    end loop;
  end loop;
  return v_out;
end $$;

revoke all on function public.register_push_device(text, text, text, text) from public, anon;
grant execute on function public.register_push_device(text, text, text, text) to authenticated;
revoke all on function public.push_due_house(timestamptz) from public, anon, authenticated;
grant execute on function public.push_due_house(timestamptz) to service_role;

-- After sending: remember it (no second time today), learn the environment; or forget a dead token.
create or replace function public.push_mark_sent(p_device uuid, p_kind text, p_date date, p_environment text)
returns void language sql security definer set search_path = public as $$
  insert into public.push_sent (device_id, kind, local_date) values (p_device, p_kind, p_date) on conflict do nothing;
  update public.push_devices set environment = coalesce(p_environment, environment) where id = p_device;
  delete from public.push_sent where sent_at < now() - interval '7 days';
$$;
create or replace function public.push_forget_device(p_device uuid)
returns void language sql security definer set search_path = public as $$
  delete from public.push_devices where id = p_device;
$$;
revoke all on function public.push_mark_sent(uuid, text, date, text), public.push_forget_device(uuid) from public, anon, authenticated;
grant execute on function public.push_mark_sent(uuid, text, date, text), public.push_forget_device(uuid) to service_role;

-- ===== 20261116120100_push_events_trigger.sql =====
-- When a house is added, create a push event for every other vacation member.
create or replace function public.note_house_added()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  v_by uuid := coalesce(auth.uid(), new.created_by);
  v_name text;
begin
  if new.deleted_at is not null then
    return new;
  end if;

  select display_name into v_name from public.profiles where id = v_by;

  insert into public.push_events (vacation_id, property_id, house_title, added_by, added_by_name)
  select new.vacation_id, new.id,
         coalesce(new.title, new.url),
         v_by, v_name
    from public.vacation_members m
   where m.vacation_id = new.vacation_id
     and m.user_id is distinct from v_by
     and exists (select 1 from public.profiles p where p.id = m.user_id and p.banned_at is null);

  return new;
end $$;

create trigger properties_house_added
  after insert on public.properties
  for each row execute function public.note_house_added();

revoke all on function public.note_house_added() from public, anon, authenticated;

-- ===== 20261116120200_push_cron.sql =====
-- House-addition push notifications: every 5 minutes, call the Edge Function push-houses
-- to send any due iOS notifications. Android not yet (phones poll locally or nothing).
select cron.schedule('holidayvote-push-houses', '*/5 * * * *', $$
  select net.http_post(
    url := (select decrypted_secret from vault.decrypted_secrets where name = 'project_url') || '/functions/v1/push-houses',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'x-cron-secret', (select decrypted_secret from vault.decrypted_secrets where name = 'report_digest_secret')
    ),
    body := '{}'::jsonb,
    timeout_milliseconds := 60000
  )
  where jsonb_array_length(public.push_due_house()) > 0
    and exists (select 1 from vault.decrypted_secrets where name = 'report_digest_secret')
    and exists (select 1 from vault.decrypted_secrets where name = 'project_url')
$$);

-- ===== 20261117170000_android_push.sql =====
-- Push devices are server-only. Legacy Android hashes cannot be reversed; those phones
-- become eligible for delivery after registering again with their actual FCM token.
alter table public.push_devices add column fcm_token text unique;
alter table public.push_devices add constraint push_devices_fcm_platform
  check (fcm_token is null or platform = 'android');

create or replace function public.register_push_device(
  p_platform text, p_token text, p_tz text, p_locale text
) returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_hash text := encode(sha256(convert_to(p_token, 'UTF8')), 'hex');
begin
  if auth.uid() is null then
    raise exception 'not_signed_in' using errcode = '42501';
  end if;
  if p_platform is null or p_platform not in ('ios', 'android') or length(coalesce(p_token, '')) < 32 then
    raise exception 'bad_device' using errcode = '22023';
  end if;
  if p_platform = 'ios' then
    insert into public.push_devices (user_id, platform, apns_token, tz, locale)
    values (auth.uid(), 'ios', p_token, p_tz, left(coalesce(p_locale, 'de'), 2))
    on conflict (apns_token) do update set user_id = excluded.user_id, tz = excluded.tz,
      locale = excluded.locale, updated_at = now();
  else
    insert into public.push_devices (user_id, platform, secret_hash, fcm_token, tz, locale)
    values (auth.uid(), 'android', v_hash, p_token, p_tz, left(coalesce(p_locale, 'de'), 2))
    on conflict (secret_hash) do update set user_id = excluded.user_id, fcm_token = excluded.fcm_token,
      tz = excluded.tz, locale = excluded.locale, updated_at = now();
  end if;
  return jsonb_build_object('ok', true);
end $$;

create or replace function public.push_due_house(p_now timestamptz default now())
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v_out jsonb := '[]'::jsonb;
  d public.push_devices;
  e public.push_events;
  v_local timestamp;
  v_msg jsonb;
  v_vac public.vacations;
begin
  for d in select * from public.push_devices
    where platform = 'ios' or (platform = 'android' and fcm_token is not null)
  loop
    v_local := p_now at time zone d.tz;

    if v_local::time < '08:00' or v_local::time >= '21:00' then
      continue;
    end if;

    if exists (
      select 1 from public.push_sent s
      where s.device_id = d.id and s.kind = 'house' and s.local_date = v_local::date
    ) then
      continue;
    end if;

    for e in select pe.*
              from public.push_events pe
              join public.properties p on p.id = pe.property_id
             where pe.vacation_id in (
               select m.vacation_id from public.vacation_members m
               where m.user_id = d.user_id
             )
               and pe.added_by is distinct from d.user_id
               and not exists (
                 select 1 from public.push_sent s
                 where s.device_id = d.id and s.kind = 'house:' || pe.id
               )
              order by pe.created_at
    loop
      select * into v_vac from public.vacations where id = e.vacation_id;
      v_msg := jsonb_build_object(
        'title', case when d.locale = 'en' then 'New holiday home' else 'Neues Ferienhaus' end,
        'body', case when d.locale = 'en'
          then coalesce(e.added_by_name, 'Someone') || ' added "' || coalesce(e.house_title, e.property_id::text) || '" to "' || v_vac.name || '".'
          else coalesce(e.added_by_name, 'Jemand') || ' hat "' || coalesce(e.house_title, e.property_id::text) || '" zu "' || v_vac.name || '" hinzugefügt.'
        end
      );
      v_out := v_out || jsonb_build_object(
        'device_id', d.id, 'platform', d.platform,
        'token', case when d.platform = 'ios' then d.apns_token else d.fcm_token end,
        'environment', d.environment,
        'kind', 'house:' || e.id, 'local_date', v_local::date,
        'title', v_msg ->> 'title', 'body', v_msg ->> 'body',
        'route', '/vacations/' || e.vacation_id || '/houses/' || e.property_id
      );
    end loop;
  end loop;
  return v_out;
end $$;

revoke all on function public.register_push_device(text, text, text, text) from public, anon;
grant execute on function public.register_push_device(text, text, text, text) to authenticated;
revoke all on function public.push_due_house(timestamptz) from public, anon, authenticated;
grant execute on function public.push_due_house(timestamptz) to service_role;
